// Keep only meetings with at least one external attendee.
// One output item per meeting, using the first external attendee as the main contact.
const cfg = $('Config').first().json;
const internalDomain = cfg.internalDomain.toLowerCase();
const personalDomains = cfg.personalEmailDomains.split(',').map(d => d.trim().toLowerCase());

const meetings = [];
for (const item of $input.all()) {
  const ev = item.json;
  const external = (ev.attendees || []).filter(a =>
    a.email && !a.resource && !a.email.toLowerCase().endsWith('@' + internalDomain)
  );
  if (external.length === 0) continue;

  const main = external[0];
  const domain = main.email.split('@')[1].toLowerCase();

  meetings.push({
    json: {
      eventId: ev.id,
      title: ev.summary || '(no title)',
      start: ev.start?.dateTime || ev.start?.date,
      meetingLink: ev.hangoutLink || '',
      agenda: ev.description || '',
      attendeeEmail: main.email,
      attendeeName: main.displayName || '',
      companyDomain: domain,
      isPersonalEmail: personalDomains.includes(domain),
      otherAttendees: external.slice(1).map(a => a.email),
    },
  });
}
return meetings;

// Combine meeting details, CRM record and website text into one prompt for the LLM.
const cfg = $('Config').first().json;
const meeting = $('Extract Meeting Details').item.json;
const crm = $('Look Up Contact in HubSpot').item.json;
const contact = crm?.results?.[0]?.properties || null;

// Strip HTML down to readable text and cap the length to control token cost.
const html = typeof $json.data === 'string' ? $json.data : '';
const websiteText = meeting.isPersonalEmail ? '' : html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, cfg.maxWebsiteChars);

const systemPrompt = `You are a sales assistant preparing a rep for an upcoming call.
Use only the information provided. If something is unknown, say so. Do not invent facts.
Return a JSON object with these keys:
"summary" (2 sentences on who this is and why the meeting matters),
"about_company" (string),
"about_person" (string),
"relationship_history" (string, based on CRM data),
"talking_points" (array of 3 to 5 strings),
"questions_to_ask" (array of 3 to 5 strings),
"risks" (array of strings, possible objections or red flags).`;

const userPrompt = `MEETING
Title: ${meeting.title}
Start: ${meeting.start}
Agenda: ${meeting.agenda || 'none'}

ATTENDEE
Name: ${meeting.attendeeName || 'unknown'}
Email: ${meeting.attendeeEmail}
Company domain: ${meeting.companyDomain}

CRM RECORD
${contact ? JSON.stringify(contact, null, 2) : 'No CRM record found. Treat as a new contact.'}

COMPANY WEBSITE (homepage text)
${websiteText || 'Not available.'}`;

return {
  json: {
    ...meeting,
    crmFound: !!contact,
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userPrompt },
    ],
  },
};

// Turn the LLM JSON output into an HTML email.
const cfg = $('Config').first().json;
const meeting = $('Build Research Context').item.json;

let brief;
try {
  brief = JSON.parse($json.choices[0].message.content);
} catch (e) {
  brief = { summary: 'The AI response could not be parsed. Check the execution log.' };
}

const list = arr => (Array.isArray(arr) && arr.length)
  ? '<ul>' + arr.map(x => `<li>${x}</li>`).join('') + '</ul>'
  : '<p>None</p>';

const startTime = new Date(meeting.start).toLocaleTimeString('en-US', {
  hour: 'numeric', minute: '2-digit', timeZone: cfg.timezone,
});

const html = `
<h2>${meeting.title}</h2>
<p><b>Time:</b> ${startTime} &nbsp; <b>With:</b> ${meeting.attendeeName || meeting.attendeeEmail} (${meeting.companyDomain})</p>
${meeting.meetingLink ? `<p><a href="${meeting.meetingLink}">Join meeting</a></p>` : ''}
<p>${brief.summary || ''}</p>
<h3>Company</h3><p>${brief.about_company || 'Unknown'}</p>
<h3>Person</h3><p>${brief.about_person || 'Unknown'}</p>
<h3>Relationship history</h3><p>${brief.relationship_history || 'No CRM record.'}</p>
<h3>Talking points</h3>${list(brief.talking_points)}
<h3>Questions to ask</h3>${list(brief.questions_to_ask)}
<h3>Risks</h3>${list(brief.risks)}
`;

return {
  json: {
    to: cfg.repEmail,
    subject: `Meeting prep: ${meeting.title} at ${startTime}`,
    html,
  },
};
